SELECT a.* FROM events a JOIN (SELECT b.* FROM chrome_attempt_bindings b WHERE b.namespace=:Namespace AND b.client_id=:ClientID AND b.profile_channel=:ProfileChannel AND b.browser_instance=:BrowserInstance AND b.broker_epoch=:BrokerEpoch AND b.channel_epoch=:ChannelEpoch AND b.scope_hash=:ScopeHash ORDER BY b.id LIMIT 65) selected ON a.namespace=selected.namespace AND a.attempt_id=selected.durable_attempt_id WHERE a.namespace=:Namespace AND a.kind IN ('outcome','effect_reconciliation')
